"use client";
// Draws the chart with Plotly from a spec computed by code.
// The chart code is fixed; nothing here is generated by AI.
import { useEffect, useRef } from "react";
import type { ChartSpec } from "@/lib/executor";
import { fmt, fmtPct } from "@/lib/format";
import type { Lang } from "@/lib/catalog";

export const COLORS = ["#0e7c66", "#e2932b", "#3d6fb6", "#b34a6b"];

type PlotlyLib = typeof import("plotly.js-basic-dist-min");
export async function loadPlotly(): Promise<PlotlyLib> {
  const mod = await import("plotly.js-basic-dist-min");
  return (mod as unknown as { default: PlotlyLib }).default ?? mod;
}

function cssVar(name: string, fallback: string): string {
  if (typeof window === "undefined") return fallback;
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim() || fallback;
}

export default function Chart({ spec, lang, pct, id }: { spec: ChartSpec; lang: Lang; pct: boolean; id: string }) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (spec.type === "kpi" || spec.type === "table" || !ref.current) return;
    let cancelled = false;
    const el = ref.current;
    loadPlotly().then((Plotly) => {
      if (cancelled) return;
      const ink = cssVar("--ink-2", "#4a5568");
      const grid = cssVar("--line", "#e5e7eb");
      const small = window.innerWidth < 560;
      const multiYear = spec.series.some((s) => s.points.length > 1);
      // Many items in one year (a ranking of regions or countries): horizontal
      // bars, highest at the top, so long names stay readable.
      const horizontal = !multiYear && spec.series.length > 5;
      const hs = [...spec.series].reverse();
      const label = (v: number) => (pct ? fmtPct(v, lang) : fmt(v, lang));
      const data = multiYear
        ? spec.series.map((s, i) => ({
            type: spec.type === "bar" ? ("bar" as const) : ("scatter" as const),
            mode: "lines+markers" as const,
            name: s.label,
            x: s.points.map((p) => p.year),
            y: s.points.map((p) => p.value),
            marker: { color: COLORS[i % COLORS.length], size: 6 },
            line: { width: 3 },
            fill: spec.series.length === 1 && spec.type !== "bar" ? ("tozeroy" as const) : undefined,
            fillcolor: spec.series.length === 1 ? "rgba(14,124,102,0.08)" : undefined,
            hovertemplate: s.points.map((p) => `${p.year}: <b>${label(p.value)}</b><extra>${s.label}</extra>`),
          }))
        : horizontal
          ? [
              {
                type: "bar" as const,
                orientation: "h" as const,
                // "Absheron-Khizi economic region" → "Absheron-Khizi": the title already says "by economic region"
                y: hs.map((s) => s.label.replace(/\s+(economic region|iqtisadi rayonu)$/i, "")),
                x: hs.map((s) => s.points[0]?.value ?? null),
                marker: { color: hs.map((s) => (s.total ? "#9aa5b1" : COLORS[0])) },
                text: hs.map((s) => (s.points[0] ? label(s.points[0].value) : "")),
                textposition: "outside" as const,
                cliponaxis: false,
                hoverinfo: "skip" as const,
              },
            ]
          : [
            {
              type: "bar" as const,
              x: spec.series.map((s) => s.label),
              y: spec.series.map((s) => s.points[0]?.value ?? null),
              marker: { color: spec.series.map((_, i) => COLORS[i % COLORS.length]) },
              text: spec.series.map((s) => (s.points[0] ? label(s.points[0].value) : "")),
              textposition: "outside" as const,
              cliponaxis: false,
              hoverinfo: "skip" as const,
            },
          ];
      Plotly.newPlot(
        el,
        data as never,
        {
          margin: { l: 8, r: 20, t: 16, b: 8 },
          height: horizontal ? Math.max(260, spec.series.length * (small ? 26 : 28) + 40) : small ? 250 : 310,
          showlegend: spec.series.length > 1 && multiYear,
          legend: { orientation: "h", y: -0.18, font: { size: 12 } },
          yaxis: horizontal
            ? { automargin: true, fixedrange: true, tickfont: { size: small ? 10 : 12 } }
            : { automargin: true, separatethousands: true, ticksuffix: pct ? "%" : "", gridcolor: grid, zerolinecolor: grid, rangemode: spec.type === "bar" && !pct ? "tozero" : "normal" },
          xaxis: horizontal
            ? {
                automargin: true,
                separatethousands: true,
                ticksuffix: pct ? "%" : "",
                gridcolor: grid,
                zerolinecolor: grid,
                fixedrange: true,
                // room for the value labels outside the longest bar
                range: [Math.min(0, ...hs.map((s) => s.points[0]?.value ?? 0)) * 1.2, Math.max(0, ...hs.map((s) => s.points[0]?.value ?? 0)) * 1.2],
                nticks: small ? 4 : 7,
              }
            : {
                automargin: true,
                gridcolor: "rgba(0,0,0,0)",
                fixedrange: true,
                // years are whole numbers: no "2 021,5" ticks and no thousands separator
                ...(multiYear ? { tickformat: "d", ...(Math.max(...spec.series.map((s) => s.points.length)) <= 12 ? { dtick: 1 } : {}) } : {}),
              },
          separators: lang === "az" ? ", " : ".,",
          paper_bgcolor: "rgba(0,0,0,0)",
          plot_bgcolor: "rgba(0,0,0,0)",
          hoverlabel: { bgcolor: "#0f1b2d", bordercolor: "#0f1b2d", font: { color: "#fff" } },
          font: { family: "inherit", size: 12, color: ink },
          dragmode: false,
        } as never,
        { displayModeBar: false, responsive: true },
      );
    });
    return () => {
      cancelled = true;
    };
  }, [spec, lang, pct]);

  if (spec.type === "kpi") {
    const s = spec.series[0];
    const p = s?.points[s.points.length - 1];
    if (!p) return null;
    return (
      <div className="kpi">
        <div className="kpi-value">{pct ? fmtPct(p.value, lang) : fmt(p.value, lang)}</div>
        <div className="kpi-label">
          {s.label} · {p.year} · {spec.unit}
        </div>
      </div>
    );
  }
  if (spec.type === "table") return null;
  return <div ref={ref} id={id} className="chart" role="img" aria-label={`${spec.title} (${spec.unit})`} />;
}
